-- 0076 — what cruisers say about each ship, category by category.
--
-- Mark, 2026-11-24: the Conga Line rating is one number per ship ("quick and dirty"); the Vacation Genie
-- places a traveler on food, things to do, service, value and so on, so the ship side has to exist per
-- ship and per category. One row = one ship on one review site, exactly as the site showed it on the
-- day it was read. Nothing is blended or adjusted here: the reading against each site's own fleet
-- average, the discount for thin review counts and the blend of the two sites all happen in
-- server/src/lib/ship-scores.ts, so the method can change without touching the captured numbers.
--
-- Read by routes/cabins.ts suggestShips, and only for the Vacation Genie (a profile is given). The Room
-- Concierge's ship suggestions do not use it. Never shown to a visitor and no site is ever named to one.
--
-- Service-role only. The rows travel with the migration so dev and prod carry the same capture.
-- Not captured (no reviews, not sailing yet): msc-world-asia, msc-world-atlantic,
-- margaritaville-at-sea-beachcomber.

CREATE TABLE IF NOT EXISTS public.ship_cruiser_scores (
  ship_slug     text NOT NULL,                 -- cabin_ships.slug
  source        text NOT NULL CHECK (source IN ('cruise_critic','cruiseline_com')),
  source_url    text NOT NULL,                 -- the page the numbers were read from
  captured_on   date NOT NULL,
  review_count  integer NOT NULL CHECK (review_count >= 0),
  overall       numeric(4,3),                  -- the site's own overall score for the ship
  -- The site's category scores under our field names. cruise_critic: cabins, dining, entertainment,
  -- public_rooms, fitness_recreation, family, embarkation, children_programs, service, value.
  -- cruiseline_com: cabins, children_programs, entertainment, dining, onboard_activities, service,
  -- ship_quality, and on older ships destinations_excursions and embarkation.
  categories    jsonb NOT NULL,
  stars         jsonb,                         -- cruise_critic only: how many 1, 2, 3, 4, 5 star reviews
  editor_rating numeric(2,1),                  -- cruise_critic only: the site's own editor's score
  passengers    integer,                       -- cruiseline_com only: passengers as the site lists them
  updated_at    timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (ship_slug, source)
);

ALTER TABLE public.ship_cruiser_scores ENABLE ROW LEVEL SECURITY;  -- no policies: service role only

COMMENT ON TABLE public.ship_cruiser_scores IS
  'Cruiser category scores per ship per review site, as captured. Feeds the Vacation Genie ship matcher through server/src/lib/ship-scores.ts. Internal only.';

-- The capture of 2026-11-24: 136 ships, both sites. A later capture replaces a row in place.
ON CONFLICT (ship_slug, source) DO UPDATE SET
  source_url = EXCLUDED.source_url, captured_on = EXCLUDED.captured_on, review_count = EXCLUDED.review_count,
  overall = EXCLUDED.overall, categories = EXCLUDED.categories, stars = EXCLUDED.stars,
  editor_rating = EXCLUDED.editor_rating, passengers = EXCLUDED.passengers, updated_at = now();
